    const int i = blockIdx.x * blockDim.x + threadIdx.x;
    const bool active = i < n;

    constexpr int tile_capacity = 1024;
    extern __shared__ Particle source_panel[];

    Particle target;
    if (active) {
        target = in[i];
    }

    const float G = 1.0f;
    const float softening = 0.001f;
    float fx = 0.0f;
