                float f = (G * target.mass * source.mass) / (distSq * dist);

                fx += f * dx;
                fy += f * dy;
                fz += f * dz;
            }
        }

        // Ensure all readers finish before this panel storage is overwritten.
        __syncthreads();
        panel_start += panel_count;
