        const int source_index = base + lane;
        if (source_index < n) {
            source_tile[lane] = in[source_index];
        }

        // All threads, including inactive tail threads, must reach both barriers.
        __syncthreads();

        const int remaining = n - base;
        const int tile_count = remaining < blockDim.x ? remaining : blockDim.x;

        if (active) {
            for (int k = 0; k < tile_count; ++k) {
                const int j = base + k;
                if (i == j) continue;

                const Particle source = source_tile[k];
                float dx = source.x - target.x;
                float dy = source.y - target.y;
                float dz = source.z - target.z;

                float distSq = dx * dx + dy * dy + dz * dz + softening;
                float dist = sqrtf(distSq);

                float f = (G * target.mass * source.mass) / (distSq * dist);

                fx += f * dx;
                fy += f * dy;
                fz += f * dz;
            }
        }

        // Ensure all readers finish before the next tile overwrites shared memory.
        __syncthreads();
    }

    if (active) {
        Particle p = target;
        p.vx += (fx / p.mass) * dt;
        p.vy += (fy / p.mass) * dt;
        p.vz += (fz / p.mass) * dt;

        p.x += p.vx * dt;
        p.y += p.vy * dt;
        p.z += p.vz * dt;

