    float x, y, z;
    float vx, vy, vz;
    float mass;
};

extern "C" __global__ void nbody_step_naive(const Particle* in, Particle* out, int n, float dt) {
    const int tid = threadIdx.x;
    const int stride = blockDim.x;
    const int i = static_cast<int>(blockIdx.x);
    if (i >= n) return;

    const float G = 1.0f;
    const float softening = 0.001f;

    __shared__ Particle target;
    __shared__ float partial_fx[256];
    __shared__ float partial_fy[256];
    __shared__ float partial_fz[256];

    if (tid == 0) target = in[i];
    __syncthreads();

    float fx = 0.0f;
    float fy = 0.0f;
    float fz = 0.0f;

    for (int j = tid; j < n;) {
        if (j != i) {
            float dx = in[j].x - target.x;
            float dy = in[j].y - target.y;
            float dz = in[j].z - target.z;

            float distSq = dx * dx + dy * dy + dz * dz + softening;
            float dist = sqrtf(distSq);
            float f = (G * target.mass * in[j].mass) / (distSq * dist);

            fx += f * dx;
            fy += f * dy;
            fz += f * dz;
        }
        if (n - j <= stride) break;
        j += stride;
    }

    partial_fx[tid] = fx;
    partial_fy[tid] = fy;
    partial_fz[tid] = fz;
    __syncthreads();

    for (int offset = stride >> 1; offset > 0; offset >>= 1) {
        if (tid < offset) {
            partial_fx[tid] += partial_fx[tid + offset];
            partial_fy[tid] += partial_fy[tid + offset];
            partial_fz[tid] += partial_fz[tid + offset];
        }
        __syncthreads();
    }

    if (tid == 0) {
        Particle p = target;
        p.vx += (partial_fx[0] / p.mass) * dt;
        p.vy += (partial_fy[0] / p.mass) * dt;
        p.vz += (partial_fz[0] / p.mass) * dt;

        p.x += p.vx * dt;
        p.y += p.vy * dt;
        p.z += p.vz * dt;

        out[i] = p;
    }
}

// Array-of-structures particle layout shared by the host and kernel.
struct Particle {
    float x, y, z;
    float vx, vy, vz;
    float mass;
};

// Each thread updates one target. Blocks cooperatively stage source tiles in
// dynamic shared memory, while each target traverses sources in index order.
extern "C" __global__ void nbody_step_naive(const Particle* in, Particle* out, int n, float dt) {
    const int lane = threadIdx.x;
    const int i = blockIdx.x * blockDim.x + lane;
    const bool active = i < n;
    extern __shared__ Particle source_tile[];

    Particle target;
    if (active) {
        target = in[i];
    }

    const float G = 1.0f;
    const float softening = 0.001f;
    float fx = 0.0f;
    float fy = 0.0f;
    float fz = 0.0f;

    const int source_tile_size = 256;
    for (int base = 0; base < n;) {
        const int remaining = n - base;
        const int tile_count = remaining < source_tile_size ? remaining : source_tile_size;

        // A 128-thread block loads up to two source particles per lane.
        const int second_offset = lane + blockDim.x;
        if (lane < tile_count) {
            source_tile[lane] = in[base + lane];
        }
        if (second_offset < tile_count) {
            source_tile[second_offset] = in[base + second_offset];
        }
        __syncthreads();

        if (active) {
            for (int k = 0; k < tile_count; ++k) {
                const int j = base + k;
                if (i == j) continue;

                const Particle source = source_tile[k];
                const float dx = source.x - target.x;
                const float dy = source.y - target.y;
                const float dz = source.z - target.z;

                const float distSq = dx * dx + dy * dy + dz * dz + softening;
                const float dist = sqrtf(distSq);
                const float f = (G * target.mass * source.mass) / (distSq * dist);

                fx += f * dx;
                fy += f * dy;
                fz += f * dz;
            }
        }

        // Inactive target threads also reach both barriers before a tile is reused.
        __syncthreads();
        base += tile_count;
    }

    if (active) {
        target.vx += (fx / target.mass) * dt;
        target.vy += (fy / target.mass) * dt;
        target.vz += (fz / target.mass) * dt;

        target.x += target.vx * dt;
        target.y += target.vy * dt;
        target.z += target.vz * dt;

        out[i] = target;
    }
}

struct Particle {
    float x, y, z;
    float vx, vy, vz;
    float mass;
};

extern "C" __global__ void nbody_step_naive(const Particle* in, Particle* out, int n, float dt) {
    constexpr int warp_width = 32;
    constexpr int warps_per_target = 4;
    const int lane = threadIdx.x % warp_width;
    const int warp = threadIdx.x / warp_width;
    const int target_group = warp / warps_per_target;
    const int warp_in_target = warp % warps_per_target;
    const long long i = (long long)blockIdx.x * 2 + target_group;

    __shared__ float partial[2][warps_per_target][3];

    Particle target = {};
    if (i < n) {
        target = in[i];
    }

    float fx = 0.0f;
    float fy = 0.0f;
    float fz = 0.0f;

    const float G = 1.0f;
    const float softening = 0.001f;
    if (i < n) {
        for (long long j = (long long)warp_in_target * warp_width + lane;
             j < (long long)n;
             j += warps_per_target * warp_width) {
            if (i == j) continue;

            const Particle source = in[j];
            const float dx = source.x - target.x;
            const float dy = source.y - target.y;
            const float dz = source.z - target.z;

            const float distSq = dx * dx + dy * dy + dz * dz + softening;
            const float dist = sqrtf(distSq);
            const float f = (G * target.mass * source.mass) / (distSq * dist);

            fx += f * dx;
            fy += f * dy;
            fz += f * dz;
        }
    }

    for (int offset = warp_width / 2; offset > 0; offset >>= 1) {
        fx += __shfl_down_sync(0xffffffffu, fx, offset);
        fy += __shfl_down_sync(0xffffffffu, fy, offset);
        fz += __shfl_down_sync(0xffffffffu, fz, offset);
    }

    if (lane == 0) {
        partial[target_group][warp_in_target][0] = fx;
        partial[target_group][warp_in_target][1] = fy;
        partial[target_group][warp_in_target][2] = fz;
    }

    __syncthreads();

    if (lane == 0 && warp_in_target == 0 && i < n) {
        float total_x = 0.0f;
        float total_y = 0.0f;
        float total_z = 0.0f;
        for (int w = 0; w < warps_per_target; ++w) {
            total_x += partial[target_group][w][0];
            total_y += partial[target_group][w][1];
            total_z += partial[target_group][w][2];
        }

        Particle p = target;
        p.vx += (total_x / p.mass) * dt;
        p.vy += (total_y / p.mass) * dt;
        p.vz += (total_z / p.mass) * dt;

        p.x += p.vx * dt;
        p.y += p.vy * dt;
        p.z += p.vz * dt;

        out[i] = p;
    }
}

