extern "C" __global__ void nbody_step_naive(const Particle* in, Particle* out, int n, float dt) {
    constexpr int COARSEN = 2;
    const unsigned int count = n > 0 ? static_cast<unsigned int>(n) : 0u;
    const unsigned int first = blockIdx.x * (blockDim.x * COARSEN) + threadIdx.x;
    if (first >= count) return;

    Particle target[COARSEN];
    unsigned int target_index[COARSEN];
    bool active[COARSEN];
    float fx[COARSEN];
    float fy[COARSEN];
    float fz[COARSEN];

    #pragma unroll
    for (int k = 0; k < COARSEN; ++k) {
        const unsigned int idx = first + static_cast<unsigned int>(k) * blockDim.x;
        target_index[k] = idx;
        active[k] = idx < count;
        fx[k] = 0.0f;
        fy[k] = 0.0f;
        fz[k] = 0.0f;
        if (active[k]) target[k] = in[idx];
    }

    const float G = 1.0f;
    const float softening = 0.001f;

    for (int j = 0; j < n; ++j) {
        const float sx = in[j].x;
        const float sy = in[j].y;
        const float sz = in[j].z;
        const float sm = in[j].mass;

        #pragma unroll
        for (int k = 0; k < COARSEN; ++k) {
            if (!active[k] || target_index[k] == static_cast<unsigned int>(j)) continue;

            const float dx = sx - target[k].x;
            const float dy = sy - target[k].y;
            const float dz = sz - target[k].z;

            const float distSq = dx * dx + dy * dy + dz * dz + softening;
            const float dist = sqrtf(distSq);
            const float f = (G * target[k].mass * sm) / (distSq * dist);

            fx[k] += f * dx;
            fy[k] += f * dy;
            fz[k] += f * dz;
        }
    }

    #pragma unroll
    for (int k = 0; k < COARSEN; ++k) {
        if (!active[k]) continue;

        target[k].vx += (fx[k] / target[k].mass) * dt;
        target[k].vy += (fy[k] / target[k].mass) * dt;
        target[k].vz += (fz[k] / target[k].mass) * dt;

        target[k].x += target[k].vx * dt;
        target[k].y += target[k].vy * dt;
        target[k].z += target[k].vz * dt;

        out[target_index[k]] = target[k];
    }
}

struct Particle {
    float x, y, z;
    float vx, vy, vz;
    float mass;
};

extern "C" __global__ void nbody_step_naive(const Particle* in, Particle* out, int n, float dt) {
    const int lanes_per_target = 16;
    const int targets_per_block = blockDim.x / lanes_per_target;
    const int group_in_block = threadIdx.x / lanes_per_target;
    const int lane_in_group = threadIdx.x % lanes_per_target;
    const int target = static_cast<int>(blockIdx.x * targets_per_block + group_in_block);

    float fx = 0.0f;
    float fy = 0.0f;
    float fz = 0.0f;
    Particle p;

    if (target < n) {
        p = in[target];

        for (long long source = lane_in_group; source < static_cast<long long>(n); source += lanes_per_target) {
            if (source == target) continue;

            float dx = in[source].x - p.x;
            float dy = in[source].y - p.y;
            float dz = in[source].z - p.z;

            float distSq = dx * dx + dy * dy + dz * dz + 0.001f;
            float dist = sqrtf(distSq);
            float f = (1.0f * p.mass * in[source].mass) / (distSq * dist);

            fx += f * dx;
            fy += f * dy;
            fz += f * dz;
        }
    }

    // Each 16-lane subgroup reduces independently; all lanes reach every shuffle.
    for (int offset = lanes_per_target / 2; offset > 0; offset >>= 1) {
        fx += __shfl_down_sync(0xffffffffu, fx, offset, lanes_per_target);
        fy += __shfl_down_sync(0xffffffffu, fy, offset, lanes_per_target);
        fz += __shfl_down_sync(0xffffffffu, fz, offset, lanes_per_target);
    }

    if (lane_in_group == 0 && target < n) {
        p.vx += (fx / p.mass) * dt;
        p.vy += (fy / p.mass) * dt;
        p.vz += (fz / p.mass) * dt;

        p.x += p.vx * dt;
        p.y += p.vy * dt;
        p.z += p.vz * dt;

        out[target] = p;
    }
}

struct Particle {
    float x, y, z;
    float vx, vy, vz;
    float mass;
};

extern "C" __global__ void nbody_step_naive(const Particle* in, Particle* out, int n, float dt) {
    const int thread = static_cast<int>(threadIdx.x);
    const int block_size = static_cast<int>(blockDim.x);
    const long long global_i = static_cast<long long>(blockIdx.x) * block_size + thread;
    const bool active = global_i < n;
    const int i = active ? static_cast<int>(global_i) : -1;

    Particle target;
    if (active) {
        target = in[i];
    }

    float fx = 0.0f;
    float fy = 0.0f;
    float fz = 0.0f;

    const int tile_capacity = 256;
    extern __shared__ float shared_x[];
    float* shared_y = shared_x + tile_capacity;
    float* shared_z = shared_y + tile_capacity;
    float* shared_mass = shared_z + tile_capacity;

    const float G = 1.0f;
    const float softening = 0.001f;

    for (int tile_start = 0; tile_start < n;) {
        const int remaining = n - tile_start;
        const int tile_count = remaining < tile_capacity ? remaining : tile_capacity;

        for (int offset = thread; offset < tile_count; offset += block_size) {
            const Particle source = in[tile_start + offset];
            shared_x[offset] = source.x;
            shared_y[offset] = source.y;
            shared_z[offset] = source.z;
            shared_mass[offset] = source.mass;
        }
        __syncthreads();

        if (active) {
            for (int offset = 0; offset < tile_count; ++offset) {
                const int j = tile_start + offset;
                if (i == j) continue;

                const float dx = shared_x[offset] - target.x;
                const float dy = shared_y[offset] - target.y;
                const float dz = shared_z[offset] - target.z;

                const float distSq = dx * dx + dy * dy + dz * dz + softening;
                const float dist = sqrtf(distSq);
                const float f = (G * target.mass * shared_mass[offset]) / (distSq * dist);

                fx += f * dx;
                fy += f * dy;
                fz += f * dz;
            }
        }
        __syncthreads();

        tile_start += tile_count;
    }

    if (active) {
        Particle p = target;
        p.vx += (fx / p.mass) * dt;
        p.vy += (fy / p.mass) * dt;
        p.vz += (fz / p.mass) * dt;

        p.x += p.vx * dt;
        p.y += p.vy * dt;
        p.z += p.vz * dt;

        out[i] = p;
    }
}

// Structure "Array of Structures" (AoS) : intuitive mais naïve sur GPU
// car elle empêche la coalescence parfaite des accès mémoire.
struct Particle {
    float x, y, z;
    float vx, vy, vz;
    float mass;
};

// Kernel CUDA naïf : Simulation gravitationnelle N-Corps (N-Body)
extern "C" __global__ void nbody_step_naive(const Particle* in, Particle* out, int n, float dt) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i >= n) return;

    const float G = 1.0f;
    const float softening = 0.001f;

    float fx = 0.0f;
    float fy = 0.0f;
    float fz = 0.0f;

    // Approche naïve : chaque thread parcourt toutes les particules en mémoire globale
    // sans utiliser de mémoire partagée (__shared__) ni mettre in[i] en registre.
    for (int j = 0; j < n; j++) {
        if (i == j) continue; // Divergence de branche inutile dans la boucle

        float dx = in[j].x - in[i].x;
        float dy = in[j].y - in[i].y;
        float dz = in[j].z - in[i].z;

        float distSq = dx * dx + dy * dy + dz * dz + softening;
        float dist = sqrtf(distSq); // Calcul coûteux (au lieu de rsqrtf)

        float f = (G * in[i].mass * in[j].mass) / (distSq * dist);

        fx += f * dx;
        fy += f * dy;
        fz += f * dz;
    }

    // Intégration d'Euler explicite
    Particle p = in[i];
    const float invMass = 1.0f / p.mass;
    p.vx += (fx * invMass) * dt;
    p.vy += (fy * invMass) * dt;
    p.vz += (fz * invMass) * dt;

    p.x += p.vx * dt;
    p.y += p.vy * dt;
    p.z += p.vz * dt;

    out[i] = p;
}

