    for (int j = 0; j < n; ++j) {
        const float sx = in[j].x;
        const float sy = in[j].y;
        const float sz = in[j].z;
        const float sm = in[j].mass;

        #pragma unroll
        for (int k = 0; k < COARSEN; ++k) {
            if (!active[k] || target_index[k] == static_cast<unsigned int>(j)) continue;

            const float dx = sx - target[k].x;
            const float dy = sy - target[k].y;
            const float dz = sz - target[k].z;

            const float distSq = dx * dx + dy * dy + dz * dz + softening;
            const float dist = sqrtf(distSq);
            const float f = (G * target[k].mass * sm) / (distSq * dist);

            fx[k] += f * dx;
            fy[k] += f * dy;
            fz[k] += f * dz;
        }
    }

    #pragma unroll
    for (int k = 0; k < COARSEN; ++k) {
        if (!active[k]) continue;

        target[k].vx += (fx[k] / target[k].mass) * dt;
        target[k].vy += (fy[k] / target[k].mass) * dt;
        target[k].vz += (fz[k] / target[k].mass) * dt;

        target[k].x += target[k].vx * dt;
        target[k].y += target[k].vy * dt;
        target[k].z += target[k].vz * dt;

        out[target_index[k]] = target[k];
    }
}

// Structure "Array of Structures" : each thread group computes one target.
struct Particle {
    float x, y, z;
    float vx, vy, vz;
    float mass;
};

// Each 8-lane subgroup partitions a target's source reduction.
extern "C" __global__ void nbody_step_naive(const Particle* in, Particle* out, int n, float dt) {
    const int lane = threadIdx.x & 31;
    const int subgroup_lane = lane & 7;
    const int target = blockIdx.x * (blockDim.x / 8) + threadIdx.x / 8;

    float fx = 0.0f;
    float fy = 0.0f;
    float fz = 0.0f;
    Particle p;

    if (target < n) {
        p = in[target];

        const float G = 1.0f;
        const float softening = 0.001f;

        for (long long j = subgroup_lane; j < n; j += 8) {
            if (j == target) continue;

            const float dx = in[j].x - p.x;
            const float dy = in[j].y - p.y;
            const float dz = in[j].z - p.z;

            const float distSq = dx * dx + dy * dy + dz * dz + softening;
            const float dist = sqrtf(distSq);
            const float f = (G * p.mass * in[j].mass) / (distSq * dist);

            fx += f * dx;
            fy += f * dy;
            fz += f * dz;
        }
    }

    // Keep every warp lane participating, including lanes for invalid targets.
    for (int offset = 4; offset > 0; offset >>= 1) {
        fx += __shfl_down_sync(0xffffffffu, fx, offset, 8);
        fy += __shfl_down_sync(0xffffffffu, fy, offset, 8);
        fz += __shfl_down_sync(0xffffffffu, fz, offset, 8);
    }

    if (subgroup_lane == 0 && target < n) {
        p.vx += (fx / p.mass) * dt;
        p.vy += (fy / p.mass) * dt;
        p.vz += (fz / p.mass) * dt;

        p.x += p.vx * dt;
        p.y += p.vy * dt;
        p.z += p.vz * dt;

        out[target] = p;
    }
}

// Structure "Array of Structures" (AoS) : intuitive mais naïve sur GPU
// car elle empêche la coalescence parfaite des accès mémoire.
struct Particle {
    float x, y, z;
    float vx, vy, vz;
    float mass;
};

// Kernel CUDA naïf : Simulation gravitationnelle N-Corps (N-Body)
extern "C" __global__ void nbody_step_naive(const Particle* in, Particle* out, int n, float dt) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i >= n) return;

    const float G = 1.0f;
    const float softening = 0.001f;

    float fx = 0.0f;
    float fy = 0.0f;
    float fz = 0.0f;

    // Chaque thread parcourt toutes les particules en mémoire globale.
    for (int j = 0; j < n; j++) {
        if (i == j) continue; // Exclure l'auto-interaction.

        float dx = in[j].x - in[i].x;
        float dy = in[j].y - in[i].y;
        float dz = in[j].z - in[i].z;

        // Accumulation float32 fusionnée de la distance au carré.
        float distSq = fmaf(dx, dx, softening);
        distSq = fmaf(dy, dy, distSq);
        distSq = fmaf(dz, dz, distSq);

        // Former distSq^(-3/2) avec le réciproque de la racine carrée.
        float invDist = rsqrtf(distSq);
        float invDistSq = invDist * invDist;
        float invDistCube = invDistSq * invDist;
        float f = (G * in[i].mass * in[j].mass) * invDistCube;

        fx += f * dx;
        fy += f * dy;
        fz += f * dz;
    }

    // Intégration d'Euler explicite
    Particle p = in[i];
    const float invMass = 1.0f / p.mass;
    p.vx += (fx * invMass) * dt;
    p.vy += (fy * invMass) * dt;
    p.vz += (fz * invMass) * dt;

    p.x += p.vx * dt;
    p.y += p.vy * dt;
    p.z += p.vz * dt;

    out[i] = p;
}

struct Particle {
    float x, y, z;
    float vx, vy, vz;
    float mass;
};

struct SourceParticle {
    float x, y, z, mass;
};

extern "C" __global__ void nbody_step_naive(const Particle* in, Particle* out, int n, float dt) {
    constexpr int source_tile_size = 512;

    const int i = blockIdx.x * blockDim.x + threadIdx.x;
    const bool active = i < n;

    Particle target;
    if (active) {
        target = in[i];
    }

    const float G = 1.0f;
    const float softening = 0.001f;
    float fx = 0.0f;
    float fy = 0.0f;
    float fz = 0.0f;

    extern __shared__ SourceParticle source_tile[];

    int base = 0;
    while (base < n) {
        int tile_count = n - base;
        if (tile_count > source_tile_size) {
            tile_count = source_tile_size;
        }

        for (int k = threadIdx.x; k < tile_count; k += blockDim.x) {
            const Particle source = in[base + k];
            source_tile[k].x = source.x;
            source_tile[k].y = source.y;
            source_tile[k].z = source.z;
            source_tile[k].mass = source.mass;
        }
        __syncthreads();

        if (active) {
            for (int k = 0; k < tile_count; ++k) {
                const int j = base + k;
                if (i != j) {
                    const SourceParticle source = source_tile[k];
                    const float dx = source.x - target.x;
                    const float dy = source.y - target.y;
                    const float dz = source.z - target.z;

                    const float distSq = dx * dx + dy * dy + dz * dz + softening;
                    const float dist = sqrtf(distSq);
                    const float f = (G * target.mass * source.mass) / (distSq * dist);

                    fx += f * dx;
                    fy += f * dy;
                    fz += f * dz;
                }
            }
        }
        __syncthreads();
        base += tile_count;
    }

    if (active) {
        target.vx += (fx / target.mass) * dt;
        target.vy += (fy / target.mass) * dt;
        target.vz += (fz / target.mass) * dt;

        target.x += target.vx * dt;
        target.y += target.vy * dt;
        target.z += target.vz * dt;

        out[i] = target;
    }
}

