// Tuiles SoA en mémoire partagée : chaque source est consommée dans l'ordre.
// Le bloc conserve 256 cibles et charge une tuile de 512 sources par passe.
extern "C" __global__ void nbody_step_naive(const Particle* in, Particle* out, int n, float dt) {
    constexpr int TILE_SIZE = 512;
    __shared__ float tile_x[TILE_SIZE];
    __shared__ float tile_y[TILE_SIZE];
    __shared__ float tile_z[TILE_SIZE];
    __shared__ float tile_mass[TILE_SIZE];

    const int lane = static_cast<int>(threadIdx.x);
    const int block_size = static_cast<int>(blockDim.x);
    const int i = static_cast<int>(blockIdx.x) * block_size + lane;
    const bool active = i < n;

    Particle target;
    if (active) {
        target = in[i];
    }

    const float G = 1.0f;
    const float softening = 0.001f;

    float fx = 0.0f;
    float fy = 0.0f;
    float fz = 0.0f;

    // Tous les threads, y compris ceux de la queue, atteignent les deux barrières.
    for (int base = 0; base < n; base += TILE_SIZE) {
        // Chaque thread charge plusieurs sources si nécessaire; les accès restent contigus.
        for (int source_offset = lane; source_offset < TILE_SIZE; source_offset += block_size) {
            if (source_offset < n - base) {
                const Particle source = in[base + source_offset];
                tile_x[source_offset] = source.x;
                tile_y[source_offset] = source.y;
                tile_z[source_offset] = source.z;
                tile_mass[source_offset] = source.mass;
            }
        }
        __syncthreads();

        int tile_count = n - base;
        if (tile_count > TILE_SIZE) {
            tile_count = TILE_SIZE;
        }

        if (active) {
            for (int offset = 0; offset < tile_count; ++offset) {
                const int j = base + offset;
                if (i == j) {
                    continue;
                }

                const float dx = tile_x[offset] - target.x;
                const float dy = tile_y[offset] - target.y;
                const float dz = tile_z[offset] - target.z;

                const float distSq = dx * dx + dy * dy + dz * dz + softening;
                const float dist = sqrtf(distSq);
                const float f = (G * target.mass * tile_mass[offset]) / (distSq * dist);

                fx += f * dx;
                fy += f * dy;
                fz += f * dz;
            }
        }
        __syncthreads();
    }

    if (!active) {
        return;
    }

    Particle p = target;
    p.vx += (fx / p.mass) * dt;
    p.vy += (fy / p.mass) * dt;
    p.vz += (fz / p.mass) * dt;

    p.x += p.vx * dt;
    p.y += p.vy * dt;
    p.z += p.vz * dt;

    out[i] = p;
}

// Chaque warp actif réutilise ses sources pour deux cibles par lane.
struct Particle {
    float x, y, z;
    float vx, vy, vz;
    float mass;
};

extern "C" __global__ void nbody_step_naive(const Particle* in, Particle* out, int n, float dt) {
    const int lane = threadIdx.x & 31;
    const int warp = threadIdx.x >> 5;
    const int active_warps = blockDim.x / 64;

    // Avec le bloc courant de 256 threads, quatre warps couvrent ses 256 cibles.
    // Les autres warps n'ont aucune cible et peuvent sortir sans participer aux shuffles.
    if (warp >= active_warps) return;

    const int warp_base = blockIdx.x * blockDim.x + warp * 64;
    if (warp_base >= n) return;

    const int i0 = warp_base + lane;
    const int i1 = i0 + 32;
    const bool valid0 = i0 < n;
    const bool valid1 = i1 < n;

    Particle p0 = {};
    Particle p1 = {};
    if (valid0) p0 = in[i0];
    if (valid1) p1 = in[i1];

    const float G = 1.0f;
    const float softening = 0.001f;
    float fx0 = 0.0f, fy0 = 0.0f, fz0 = 0.0f;
    float fx1 = 0.0f, fy1 = 0.0f, fz1 = 0.0f;

    // Toutes les lanes d'un warp actif restent présentes aux shuffles,
    // y compris celles dont une ou deux cibles sont hors de la queue.
    for (int base = 0; base < n; ) {
        const int source_index = base + lane;
        float sx_lane = 0.0f;
        float sy_lane = 0.0f;
        float sz_lane = 0.0f;
        float sm_lane = 0.0f;
        if (source_index < n) {
            const Particle& source = in[source_index];
            sx_lane = source.x;
            sy_lane = source.y;
            sz_lane = source.z;
            sm_lane = source.mass;
        }

        const int remaining = n - base;
        const int source_count = remaining < 32 ? remaining : 32;
        for (int s = 0; s < source_count; ++s) {
            const int j = base + s;
            const float sx = __shfl_sync(0xffffffffu, sx_lane, s);
            const float sy = __shfl_sync(0xffffffffu, sy_lane, s);
            const float sz = __shfl_sync(0xffffffffu, sz_lane, s);
            const float sm = __shfl_sync(0xffffffffu, sm_lane, s);

            if (j < n) {
                if (valid0 && i0 != j) {
                    const float dx = sx - p0.x;
                    const float dy = sy - p0.y;
                    const float dz = sz - p0.z;
                    const float distSq = dx * dx + dy * dy + dz * dz + softening;
                    const float dist = sqrtf(distSq);
                    const float f = (G * p0.mass * sm) / (distSq * dist);
                    fx0 += f * dx;
                    fy0 += f * dy;
                    fz0 += f * dz;
                }
                if (valid1 && i1 != j) {
                    const float dx = sx - p1.x;
                    const float dy = sy - p1.y;
                    const float dz = sz - p1.z;
                    const float distSq = dx * dx + dy * dy + dz * dz + softening;
                    const float dist = sqrtf(distSq);
                    const float f = (G * p1.mass * sm) / (distSq * dist);
                    fx1 += f * dx;
                    fy1 += f * dy;
                    fz1 += f * dz;
                }
            }
        }

        if (remaining <= 32) break;
        base += 32;
    }

    if (valid0) {
        p0.vx += (fx0 / p0.mass) * dt;
        p0.vy += (fy0 / p0.mass) * dt;
        p0.vz += (fz0 / p0.mass) * dt;
        p0.x += p0.vx * dt;
        p0.y += p0.vy * dt;
        p0.z += p0.vz * dt;
        out[i0] = p0;
    }
    if (valid1) {
        p1.vx += (fx1 / p1.mass) * dt;
        p1.vy += (fy1 / p1.mass) * dt;
        p1.vz += (fz1 / p1.mass) * dt;
        p1.x += p1.vx * dt;
        p1.y += p1.vy * dt;
        p1.z += p1.vz * dt;
        out[i1] = p1;
    }
}

struct Particle {
    float x, y, z;
    float vx, vy, vz;
    float mass;
};

extern "C" __global__ void nbody_step_naive(const Particle* in, Particle* out, int n, float dt) {
    const long long block_base = static_cast<long long>(blockIdx.x) *
                                 static_cast<long long>(blockDim.x) * 2LL;
    const long long i0 = block_base + static_cast<long long>(threadIdx.x);
    const long long i1 = i0 + static_cast<long long>(blockDim.x);

    const bool valid0 = i0 < n;
    const bool valid1 = i1 < n;
    if (!valid0 && !valid1) return;

    Particle p0;
    Particle p1;
    if (valid0) p0 = in[i0];
    if (valid1) p1 = in[i1];

    float fx0 = 0.0f, fy0 = 0.0f, fz0 = 0.0f;
    float fx1 = 0.0f, fy1 = 0.0f, fz1 = 0.0f;

    const float G = 1.0f;
    const float softening = 0.001f;

    for (int j = 0; j < n; ++j) {
        const Particle source = in[j];

        if (valid0 && i0 != j) {
            const float dx = source.x - p0.x;
            const float dy = source.y - p0.y;
            const float dz = source.z - p0.z;
            const float distSq = dx * dx + dy * dy + dz * dz + softening;
            const float dist = sqrtf(distSq);
            const float f = (G * p0.mass * source.mass) / (distSq * dist);
            fx0 += f * dx;
            fy0 += f * dy;
            fz0 += f * dz;
        }

        if (valid1 && i1 != j) {
            const float dx = source.x - p1.x;
            const float dy = source.y - p1.y;
            const float dz = source.z - p1.z;
            const float distSq = dx * dx + dy * dy + dz * dz + softening;
            const float dist = sqrtf(distSq);
            const float f = (G * p1.mass * source.mass) / (distSq * dist);
            fx1 += f * dx;
            fy1 += f * dy;
            fz1 += f * dz;
        }
    }

    if (valid0) {
        p0.vx += (fx0 / p0.mass) * dt;
        p0.vy += (fy0 / p0.mass) * dt;
        p0.vz += (fz0 / p0.mass) * dt;
        p0.x += p0.vx * dt;
        p0.y += p0.vy * dt;
        p0.z += p0.vz * dt;
        out[i0] = p0;
    }

    if (valid1) {
        p1.vx += (fx1 / p1.mass) * dt;
        p1.vy += (fy1 / p1.mass) * dt;
        p1.vz += (fz1 / p1.mass) * dt;
        p1.x += p1.vx * dt;
        p1.y += p1.vy * dt;
        p1.z += p1.vz * dt;
        out[i1] = p1;
    }
}

struct Particle {
    float x, y, z;
    float vx, vy, vz;
    float mass;
};

extern "C" __global__ void nbody_step_naive(const Particle* in, Particle* out, int n, float dt) {
    const int tile_size = 256;
    __shared__ float source_x[256];
    __shared__ float source_y[256];
    __shared__ float source_z[256];
    __shared__ float source_mass[256];

    const int thread_id = threadIdx.x;
    const int first_target = blockIdx.x * 256 + thread_id;
    const int second_target = first_target + blockDim.x;
    const bool first_valid = first_target < n;
    const bool second_valid = second_target < n;

    Particle first_particle;
    Particle second_particle;
    if (first_valid) {
        first_particle = in[first_target];
    }
    if (second_valid) {
        second_particle = in[second_target];
    }

    const float G = 1.0f;
    const float softening = 0.001f;
    float first_fx = 0.0f;
    float first_fy = 0.0f;
    float first_fz = 0.0f;
    float second_fx = 0.0f;
    float second_fy = 0.0f;
    float second_fz = 0.0f;

    for (int tile_start = 0; tile_start < n; tile_start += tile_size) {
        const int remaining = n - tile_start;
        const int tile_count = remaining < tile_size ? remaining : tile_size;

        // Each thread loads two sources for this 256-element tile.
        for (int k = thread_id; k < tile_size; k += blockDim.x) {
            if (k < tile_count) {
                const Particle source = in[tile_start + k];
                source_x[k] = source.x;
                source_y[k] = source.y;
                source_z[k] = source.z;
                source_mass[k] = source.mass;
            }
        }
        __syncthreads();

        for (int k = 0; k < tile_count; ++k) {
            const int j = tile_start + k;
            const float sx = source_x[k];
            const float sy = source_y[k];
            const float sz = source_z[k];
            const float sm = source_mass[k];

            if (first_valid && first_target != j) {
                const float dx = sx - first_particle.x;
                const float dy = sy - first_particle.y;
                const float dz = sz - first_particle.z;
                const float distSq = dx * dx + dy * dy + dz * dz + softening;
                const float dist = sqrtf(distSq);
                const float f = (G * first_particle.mass * sm) / (distSq * dist);
                first_fx += f * dx;
                first_fy += f * dy;
                first_fz += f * dz;
            }

            if (second_valid && second_target != j) {
                const float dx = sx - second_particle.x;
                const float dy = sy - second_particle.y;
                const float dz = sz - second_particle.z;
                const float distSq = dx * dx + dy * dy + dz * dz + softening;
                const float dist = sqrtf(distSq);
                const float f = (G * second_particle.mass * sm) / (distSq * dist);
                second_fx += f * dx;
                second_fy += f * dy;
                second_fz += f * dz;
            }
        }

        // All threads, including those without a valid target, must reach this barrier.
        __syncthreads();
    }

    if (first_valid) {
        first_particle.vx += (first_fx / first_particle.mass) * dt;
        first_particle.vy += (first_fy / first_particle.mass) * dt;
        first_particle.vz += (first_fz / first_particle.mass) * dt;
        first_particle.x += first_particle.vx * dt;
        first_particle.y += first_particle.vy * dt;
        first_particle.z += first_particle.vz * dt;
        out[first_target] = first_particle;
    }

    if (second_valid) {
        second_particle.vx += (second_fx / second_particle.mass) * dt;
        second_particle.vy += (second_fy / second_particle.mass) * dt;
        second_particle.vz += (second_fz / second_particle.mass) * dt;
        second_particle.x += second_particle.vx * dt;
        second_particle.y += second_particle.vy * dt;
        second_particle.z += second_particle.vz * dt;
        out[second_target] = second_particle;
    }
}

// Particle positions, velocities, and mass use an array-of-structures layout.
struct Particle {
    float x, y, z;
    float vx, vy, vz;
    float mass;
};

// Each warp loads a source tile by lane, then broadcasts its fields to the
// target lanes. All lanes in a participating warp execute every shuffle.
extern "C" __global__ void nbody_step_naive(const Particle* in, Particle* out, int n, float dt) {
    const int i = blockIdx.x * blockDim.x + threadIdx.x;
    const int lane = threadIdx.x & 31;
    const int warp_first_target = i - lane;

    // This is warp-uniform, so no lane in a participating warp exits early.
    if (warp_first_target >= n) return;

    const bool target_valid = i < n;
    Particle p;
    if (target_valid) p = in[i];

    const float G = 1.0f;
    const float softening = 0.001f;
    float fx = 0.0f;
    float fy = 0.0f;
    float fz = 0.0f;

    int source_base = 0;
    while (source_base < n) {
        const int remaining = n - source_base;
        const int source_count = remaining < 32 ? remaining : 32;

        float tile_x = 0.0f;
        float tile_y = 0.0f;
        float tile_z = 0.0f;
        float tile_mass = 0.0f;
        if (lane < source_count) {
            const int source_index = source_base + lane;
            tile_x = in[source_index].x;
            tile_y = in[source_index].y;
            tile_z = in[source_index].z;
            tile_mass = in[source_index].mass;
        }

        // Static unrolling removes the source-lane loop branch. Invalid tail
        // sources still participate in shuffles but never contribute.
        #pragma unroll 32
        for (int k = 0; k < 32; ++k) {
            const float sx = __shfl_sync(0xffffffffu, tile_x, k);
            const float sy = __shfl_sync(0xffffffffu, tile_y, k);
            const float sz = __shfl_sync(0xffffffffu, tile_z, k);
            const float source_mass = __shfl_sync(0xffffffffu, tile_mass, k);

            if (k < source_count) {
                const int j = source_base + k;
                if (target_valid && i != j) {
                    const float dx = sx - p.x;
                    const float dy = sy - p.y;
                    const float dz = sz - p.z;

                    const float distSq = dx * dx + dy * dy + dz * dz + softening;
                    const float dist = sqrtf(distSq);
                    const float f = (G * p.mass * source_mass) / (distSq * dist);

                    fx += f * dx;
                    fy += f * dy;
                    fz += f * dz;
                }
            }
        }

        if (remaining <= 32) break;
        source_base += 32;
    }

    if (target_valid) {
        p.vx += (fx / p.mass) * dt;
        p.vy += (fy / p.mass) * dt;
        p.vz += (fz / p.mass) * dt;

        p.x += p.vx * dt;
        p.y += p.vy * dt;
        p.z += p.vz * dt;

        out[i] = p;
    }
}

struct Particle {
    float x, y, z;
    float vx, vy, vz;
    float mass;
};

extern "C" __global__ void nbody_step_naive(const Particle* in, Particle* out, int n, float dt) {
    const int tile_size = 256;
    const int tid = (int)threadIdx.x;
    const int first_target = (int)blockIdx.x * (2 * (int)blockDim.x) + tid;
    const int second_target = first_target + (int)blockDim.x;
    const bool first_valid = first_target < n;
    const bool second_valid = second_target < n;

    const float G = 1.0f;
    const float softening = 0.001f;

    const float x0 = first_valid ? in[first_target].x : 0.0f;
    const float y0 = first_valid ? in[first_target].y : 0.0f;
    const float z0 = first_valid ? in[first_target].z : 0.0f;
    const float mass0 = first_valid ? in[first_target].mass : 0.0f;
    const float x1 = second_valid ? in[second_target].x : 0.0f;
    const float y1 = second_valid ? in[second_target].y : 0.0f;
    const float z1 = second_valid ? in[second_target].z : 0.0f;
    const float mass1 = second_valid ? in[second_target].mass : 0.0f;

    float fx0 = 0.0f;
    float fy0 = 0.0f;
    float fz0 = 0.0f;
    float fx1 = 0.0f;
    float fy1 = 0.0f;
    float fz1 = 0.0f;

    __shared__ float tile_x[256];
    __shared__ float tile_y[256];
    __shared__ float tile_z[256];
    __shared__ float tile_mass[256];

    for (int tile_start = 0; tile_start < n; tile_start += tile_size) {
        const int source_index = tile_start + tid;
        if (source_index < n) {
            tile_x[tid] = in[source_index].x;
            tile_y[tid] = in[source_index].y;
            tile_z[tid] = in[source_index].z;
            tile_mass[tid] = in[source_index].mass;
        } else {
            tile_x[tid] = 0.0f;
            tile_y[tid] = 0.0f;
            tile_z[tid] = 0.0f;
            tile_mass[tid] = 0.0f;
        }
        __syncthreads();

        const int remaining = n - tile_start;
        const int tile_count = remaining < tile_size ? remaining : tile_size;
        for (int k = 0; k < tile_count; ++k) {
            const int j = tile_start + k;
            const float sx = tile_x[k];
            const float sy = tile_y[k];
            const float sz = tile_z[k];
            const float smass = tile_mass[k];

            if (first_valid && first_target != j) {
                const float dx = sx - x0;
                const float dy = sy - y0;
                const float dz = sz - z0;
                const float distSq = dx * dx + dy * dy + dz * dz + softening;
                const float dist = sqrtf(distSq);
                const float f = (G * mass0 * smass) / (distSq * dist);
                fx0 += f * dx;
                fy0 += f * dy;
                fz0 += f * dz;
            }

            if (second_valid && second_target != j) {
                const float dx = sx - x1;
                const float dy = sy - y1;
                const float dz = sz - z1;
                const float distSq = dx * dx + dy * dy + dz * dz + softening;
                const float dist = sqrtf(distSq);
                const float f = (G * mass1 * smass) / (distSq * dist);
                fx1 += f * dx;
                fy1 += f * dy;
                fz1 += f * dz;
            }
        }
        __syncthreads();
    }

    if (first_valid) {
        Particle p = in[first_target];
        p.vx += (fx0 / p.mass) * dt;
        p.vy += (fy0 / p.mass) * dt;
        p.vz += (fz0 / p.mass) * dt;
        p.x += p.vx * dt;
        p.y += p.vy * dt;
        p.z += p.vz * dt;
        out[first_target] = p;
    }

    if (second_valid) {
        Particle p = in[second_target];
        p.vx += (fx1 / p.mass) * dt;
        p.vy += (fy1 / p.mass) * dt;
        p.vz += (fz1 / p.mass) * dt;
        p.x += p.vx * dt;
        p.y += p.vy * dt;
        p.z += p.vz * dt;
        out[second_target] = p;
    }
}

struct Particle {
    float x, y, z;
    float vx, vy, vz;
    float mass;
};

extern "C" __global__ void nbody_step_naive(const Particle* in, Particle* out, int n, float dt) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i >= n) return;

    const float G = 1.0f;
    const float softening = 0.001f;

    float fx = 0.0f;
    float fy = 0.0f;
    float fz = 0.0f;

    for (int j = 0; j < n; j++) {
        if (i == j) continue;

        float dx = in[j].x - in[i].x;
        float dy = in[j].y - in[i].y;
        float dz = in[j].z - in[i].z;

        float distSq = fmaf(dx, dx, fmaf(dy, dy, fmaf(dz, dz, softening)));
        float dist = sqrtf(distSq);

        float f = (G * in[i].mass * in[j].mass) / (distSq * dist);

        fx += f * dx;
        fy += f * dy;
        fz += f * dz;
    }

    Particle p = in[i];
    p.vx += (fx / p.mass) * dt;
    p.vy += (fy / p.mass) * dt;
    p.vz += (fz / p.mass) * dt;

    p.x += p.vx * dt;
    p.y += p.vy * dt;
    p.z += p.vz * dt;

    out[i] = p;
}

struct Particle {
    float x, y, z;
    float vx, vy, vz;
    float mass;
};

__device__ __forceinline__ void accumulate_source(
    const Particle& target,
    int target_index,
    int source_index,
    float sx,
    float sy,
    float sz,
    float source_mass,
    float& fx,
    float& fy,
    float& fz) {
    if (target_index == source_index) return;

    const float G = 1.0f;
    const float softening = 0.001f;
    const float dx = sx - target.x;
    const float dy = sy - target.y;
    const float dz = sz - target.z;

    const float distSq = dx * dx + dy * dy + dz * dz + softening;
    const float dist = sqrtf(distSq);
    const float f = (G * target.mass * source_mass) / (distSq * dist);

    fx += f * dx;
    fy += f * dy;
    fz += f * dz;
}

extern "C" __global__ void nbody_step_naive(const Particle* in, Particle* out, int n, float dt) {
    const long long block_base = static_cast<long long>(blockIdx.x) *
                                 static_cast<long long>(blockDim.x) * 4LL;
    const long long i0 = block_base + static_cast<long long>(threadIdx.x);
    const long long i1 = i0 + static_cast<long long>(blockDim.x);
    const long long i2 = i1 + static_cast<long long>(blockDim.x);
    const long long i3 = i2 + static_cast<long long>(blockDim.x);

    const bool valid0 = i0 < n;
    const bool valid1 = i1 < n;
    const bool valid2 = i2 < n;
    const bool valid3 = i3 < n;
    if (!valid0 && !valid1 && !valid2 && !valid3) return;

    Particle p0;
    Particle p1;
    Particle p2;
    Particle p3;
    if (valid0) p0 = in[i0];
    if (valid1) p1 = in[i1];
    if (valid2) p2 = in[i2];
    if (valid3) p3 = in[i3];

    float fx0 = 0.0f, fy0 = 0.0f, fz0 = 0.0f;
    float fx1 = 0.0f, fy1 = 0.0f, fz1 = 0.0f;
    float fx2 = 0.0f, fy2 = 0.0f, fz2 = 0.0f;
    float fx3 = 0.0f, fy3 = 0.0f, fz3 = 0.0f;

    for (int j = 0; j < n; ++j) {
        const Particle source = in[j];
        const float sx = source.x;
        const float sy = source.y;
        const float sz = source.z;
        const float source_mass = source.mass;

        if (valid0) {
            accumulate_source(p0, static_cast<int>(i0), j, sx, sy, sz, source_mass,
                              fx0, fy0, fz0);
        }
        if (valid1) {
            accumulate_source(p1, static_cast<int>(i1), j, sx, sy, sz, source_mass,
                              fx1, fy1, fz1);
        }
        if (valid2) {
            accumulate_source(p2, static_cast<int>(i2), j, sx, sy, sz, source_mass,
                              fx2, fy2, fz2);
        }
        if (valid3) {
            accumulate_source(p3, static_cast<int>(i3), j, sx, sy, sz, source_mass,
                              fx3, fy3, fz3);
        }
    }

    if (valid0) {
        p0.vx += (fx0 / p0.mass) * dt;
        p0.vy += (fy0 / p0.mass) * dt;
        p0.vz += (fz0 / p0.mass) * dt;
        p0.x += p0.vx * dt;
        p0.y += p0.vy * dt;
        p0.z += p0.vz * dt;
        out[i0] = p0;
    }

    if (valid1) {
        p1.vx += (fx1 / p1.mass) * dt;
        p1.vy += (fy1 / p1.mass) * dt;
        p1.vz += (fz1 / p1.mass) * dt;
        p1.x += p1.vx * dt;
        p1.y += p1.vy * dt;
        p1.z += p1.vz * dt;
        out[i1] = p1;
    }

    if (valid2) {
        p2.vx += (fx2 / p2.mass) * dt;
        p2.vy += (fy2 / p2.mass) * dt;
        p2.vz += (fz2 / p2.mass) * dt;
        p2.x += p2.vx * dt;
        p2.y += p2.vy * dt;
        p2.z += p2.vz * dt;
        out[i2] = p2;
    }

    if (valid3) {
        p3.vx += (fx3 / p3.mass) * dt;
        p3.vy += (fy3 / p3.mass) * dt;
        p3.vz += (fz3 / p3.mass) * dt;
        p3.x += p3.vx * dt;
        p3.y += p3.vy * dt;
        p3.z += p3.vz * dt;
        out[i3] = p3;
    }
}

// Chaque warp actif réutilise ses sources pour deux cibles par lane.
struct Particle {
    float x, y, z;
    float vx, vy, vz;
    float mass;
};

extern "C" __global__ void nbody_step_naive(const Particle* in, Particle* out, int n, float dt) {
    const int lane = threadIdx.x & 31;
    const int warp = threadIdx.x >> 5;
    const int active_warps = blockDim.x / 32;

    // Avec 128 threads, les quatre warps du bloc couvrent 256 cibles.
    if (warp >= active_warps) return;

    const int warp_base = blockIdx.x * blockDim.x * 2 + warp * 64;
    if (warp_base >= n) return;

    const int i0 = warp_base + lane;
    const int i1 = i0 + 32;
    const bool valid0 = i0 < n;
    const bool valid1 = i1 < n;

    Particle p0 = {};
    Particle p1 = {};
    if (valid0) p0 = in[i0];
    if (valid1) p1 = in[i1];

    const float G = 1.0f;
    const float softening = 0.001f;
    float fx0 = 0.0f, fy0 = 0.0f, fz0 = 0.0f;
    float fx1 = 0.0f, fy1 = 0.0f, fz1 = 0.0f;

    // Toutes les lanes d'un warp actif restent présentes aux shuffles,
    // y compris celles dont une ou deux cibles sont hors de la queue.
    for (int base = 0; base < n; ) {
        const int source_index = base + lane;
        float sx_lane = 0.0f;
        float sy_lane = 0.0f;
        float sz_lane = 0.0f;
        float sm_lane = 0.0f;
        if (source_index < n) {
            const Particle& source = in[source_index];
            sx_lane = source.x;
            sy_lane = source.y;
            sz_lane = source.z;
            sm_lane = source.mass;
        }

        const int remaining = n - base;
        const int source_count = remaining < 32 ? remaining : 32;
        for (int s = 0; s < source_count; ++s) {
            const int j = base + s;
            const float sx = __shfl_sync(0xffffffffu, sx_lane, s);
            const float sy = __shfl_sync(0xffffffffu, sy_lane, s);
            const float sz = __shfl_sync(0xffffffffu, sz_lane, s);
            const float sm = __shfl_sync(0xffffffffu, sm_lane, s);

            if (j < n) {
                if (valid0 && i0 != j) {
                    const float dx = sx - p0.x;
                    const float dy = sy - p0.y;
                    const float dz = sz - p0.z;
                    const float distSq = dx * dx + dy * dy + dz * dz + softening;
                    const float dist = sqrtf(distSq);
                    const float f = (G * p0.mass * sm) / (distSq * dist);
                    fx0 += f * dx;
                    fy0 += f * dy;
                    fz0 += f * dz;
                }
                if (valid1 && i1 != j) {
                    const float dx = sx - p1.x;
                    const float dy = sy - p1.y;
                    const float dz = sz - p1.z;
                    const float distSq = dx * dx + dy * dy + dz * dz + softening;
                    const float dist = sqrtf(distSq);
                    const float f = (G * p1.mass * sm) / (distSq * dist);
                    fx1 += f * dx;
                    fy1 += f * dy;
                    fz1 += f * dz;
                }
            }
        }

        if (remaining <= 32) break;
        base += 32;
    }

    if (valid0) {
        p0.vx += (fx0 / p0.mass) * dt;
        p0.vy += (fy0 / p0.mass) * dt;
        p0.vz += (fz0 / p0.mass) * dt;
        p0.x += p0.vx * dt;
        p0.y += p0.vy * dt;
        p0.z += p0.vz * dt;
        out[i0] = p0;
    }
    if (valid1) {
        p1.vx += (fx1 / p1.mass) * dt;
        p1.vy += (fy1 / p1.mass) * dt;
        p1.vz += (fz1 / p1.mass) * dt;
        p1.x += p1.vx * dt;
        p1.y += p1.vy * dt;
        p1.z += p1.vz * dt;
        out[i1] = p1;
    }
}

