// Chaque thread traite deux cibles et réutilise chaque source pour les deux.
extern "C" __global__ void nbody_step_naive(const Particle* in, Particle* out, int n, float dt) {
    const unsigned long long first =
        static_cast<unsigned long long>(blockIdx.x) * (2ULL * blockDim.x) + threadIdx.x;
    const unsigned long long second = first + blockDim.x;
    const unsigned long long count = static_cast<unsigned long long>(n);
    const bool valid0 = first < count;
    const bool valid1 = second < count;

    if (!valid0 && !valid1) return;

    const float G = 1.0f;
    const float softening = 0.001f;

    Particle p0;
    Particle p1;
    float fx0 = 0.0f, fy0 = 0.0f, fz0 = 0.0f;
    float fx1 = 0.0f, fy1 = 0.0f, fz1 = 0.0f;

    if (valid0) p0 = in[first];
    if (valid1) p1 = in[second];

    for (int j = 0; j < n; ++j) {
        const Particle source = in[j];

        if (valid0 && first != static_cast<unsigned long long>(j)) {
            const float dx = source.x - p0.x;
            const float dy = source.y - p0.y;
            const float dz = source.z - p0.z;
            const float distSq = dx * dx + dy * dy + dz * dz + softening;
            const float dist = sqrtf(distSq);
            const float f = (G * p0.mass * source.mass) / (distSq * dist);
            fx0 += f * dx;
            fy0 += f * dy;
            fz0 += f * dz;
        }

        if (valid1 && second != static_cast<unsigned long long>(j)) {
            const float dx = source.x - p1.x;
            const float dy = source.y - p1.y;
            const float dz = source.z - p1.z;
            const float distSq = dx * dx + dy * dy + dz * dz + softening;
            const float dist = sqrtf(distSq);
            const float f = (G * p1.mass * source.mass) / (distSq * dist);
            fx1 += f * dx;
            fy1 += f * dy;
            fz1 += f * dz;
        }
    }

    if (valid0) {
        p0.vx += (fx0 / p0.mass) * dt;
        p0.vy += (fy0 / p0.mass) * dt;
        p0.vz += (fz0 / p0.mass) * dt;
        p0.x += p0.vx * dt;
        p0.y += p0.vy * dt;
        p0.z += p0.vz * dt;
        out[first] = p0;
    }

    if (valid1) {
        p1.vx += (fx1 / p1.mass) * dt;
        p1.vy += (fy1 / p1.mass) * dt;
        p1.vz += (fz1 / p1.mass) * dt;
        p1.x += p1.vx * dt;
        p1.y += p1.vy * dt;
        p1.z += p1.vz * dt;
        out[second] = p1;
    }
}

// Structure "Array of Structures" (AoS) : intuitive mais naïve sur GPU
// car elle empêche la coalescence parfaite des accès mémoire.
struct Particle {
    float x, y, z;
    float vx, vy, vz;
    float mass;
};

// Chaque warp charge un tile de sources par lanes, puis diffuse chaque
// source par shuffle aux lanes qui accumulent leurs cibles. Le tile suivant
// est préchargé pendant le calcul du tile courant.
extern "C" __global__ void nbody_step_naive(const Particle* in, Particle* out, int n, float dt) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    int lane = threadIdx.x & 31;
    bool target_valid = i < n;

    // Ne pas faire sortir les lanes invalides : elles participent aux shuffles
    // nécessaires aux autres cibles du warp.
    Particle p = {};
    if (target_valid) p = in[i];

    const float G = 1.0f;
    const float softening = 0.001f;
    float fx = 0.0f;
    float fy = 0.0f;
    float fz = 0.0f;

    int base = 0;
    int valid_sources = n < 32 ? n : 32;
    float sx_lane = 0.0f;
    float sy_lane = 0.0f;
    float sz_lane = 0.0f;
    float sm_lane = 0.0f;
    if (lane < valid_sources) {
        const Particle& source = in[lane];
        sx_lane = source.x;
        sy_lane = source.y;
        sz_lane = source.z;
        sm_lane = source.mass;
    }

    // Le parcours par tiles conserve l'ordre croissant des indices source.
    while (base < n) {
        int remaining = n - base;
        int next_sources = remaining > 32 ? remaining - 32 : 0;
        if (next_sources > 32) next_sources = 32;

        // Charger par lane le prochain tile avant les shuffles et le calcul
        // du tile courant afin de pouvoir recouvrir une partie de la latence.
        float next_sx_lane = 0.0f;
        float next_sy_lane = 0.0f;
        float next_sz_lane = 0.0f;
        float next_sm_lane = 0.0f;
        if (lane < next_sources) {
            const Particle& next_source = in[base + 32 + lane];
            next_sx_lane = next_source.x;
            next_sy_lane = next_source.y;
            next_sz_lane = next_source.z;
            next_sm_lane = next_source.mass;
        }

        for (int s = 0; s < 32; ++s) {
            float sx = __shfl_sync(0xffffffffu, sx_lane, s);
            float sy = __shfl_sync(0xffffffffu, sy_lane, s);
            float sz = __shfl_sync(0xffffffffu, sz_lane, s);
            float sm = __shfl_sync(0xffffffffu, sm_lane, s);

            if (target_valid && s < valid_sources) {
                int j = base + s;
                if (i != j) {
                    float dx = sx - p.x;
                    float dy = sy - p.y;
                    float dz = sz - p.z;
                    float distSq = dx * dx + dy * dy + dz * dz + softening;
                    float dist = sqrtf(distSq);
                    float f = (G * p.mass * sm) / (distSq * dist);
                    fx += f * dx;
                    fy += f * dy;
                    fz += f * dz;
                }
            }
        }

        if (remaining <= 32) break;
        sx_lane = next_sx_lane;
        sy_lane = next_sy_lane;
        sz_lane = next_sz_lane;
        sm_lane = next_sm_lane;
        valid_sources = next_sources;
        base += 32;
    }

    if (target_valid) {
        p.vx += (fx / p.mass) * dt;
        p.vy += (fy / p.mass) * dt;
        p.vz += (fz / p.mass) * dt;
        p.x += p.vx * dt;
        p.y += p.vy * dt;
        p.z += p.vz * dt;
        out[i] = p;
    }
}

struct Particle {
    float x, y, z;
    float vx, vy, vz;
    float mass;
};

extern "C" __global__ void nbody_step_naive(const Particle* in, Particle* out, int n, float dt) {
    const int tile_size = 1024;
    const int tid = (int)threadIdx.x;
    const int first_target = (int)blockIdx.x * (2 * (int)blockDim.x) + tid;
    const int second_target = first_target + (int)blockDim.x;
    const bool first_valid = first_target < n;
    const bool second_valid = second_target < n;

    const float G = 1.0f;
    const float softening = 0.001f;

    const float x0 = first_valid ? in[first_target].x : 0.0f;
    const float y0 = first_valid ? in[first_target].y : 0.0f;
    const float z0 = first_valid ? in[first_target].z : 0.0f;
    const float mass0 = first_valid ? in[first_target].mass : 0.0f;
    const float x1 = second_valid ? in[second_target].x : 0.0f;
    const float y1 = second_valid ? in[second_target].y : 0.0f;
    const float z1 = second_valid ? in[second_target].z : 0.0f;
    const float mass1 = second_valid ? in[second_target].mass : 0.0f;

    float fx0 = 0.0f;
    float fy0 = 0.0f;
    float fz0 = 0.0f;
    float fx1 = 0.0f;
    float fy1 = 0.0f;
    float fz1 = 0.0f;

    __shared__ float tile_x[1024];
    __shared__ float tile_y[1024];
    __shared__ float tile_z[1024];
    __shared__ float tile_mass[1024];

    for (int tile_start = 0; tile_start < n;) {
        const int remaining = n - tile_start;
        const int tile_count = remaining < tile_size ? remaining : tile_size;

        for (int tile_slot = tid; tile_slot < tile_size; tile_slot += (int)blockDim.x) {
            if (tile_slot < tile_count) {
                const Particle source = in[tile_start + tile_slot];
                tile_x[tile_slot] = source.x;
                tile_y[tile_slot] = source.y;
                tile_z[tile_slot] = source.z;
                tile_mass[tile_slot] = source.mass;
            } else {
                tile_x[tile_slot] = 0.0f;
                tile_y[tile_slot] = 0.0f;
                tile_z[tile_slot] = 0.0f;
                tile_mass[tile_slot] = 0.0f;
            }
        }
        __syncthreads();

        for (int k = 0; k < tile_count; ++k) {
            const int j = tile_start + k;
            const float sx = tile_x[k];
            const float sy = tile_y[k];
            const float sz = tile_z[k];
            const float smass = tile_mass[k];

            if (first_valid && first_target != j) {
                const float dx = sx - x0;
                const float dy = sy - y0;
                const float dz = sz - z0;
                const float distSq = dx * dx + dy * dy + dz * dz + softening;
                const float dist = sqrtf(distSq);
                const float f = (G * mass0 * smass) / (distSq * dist);
                fx0 += f * dx;
                fy0 += f * dy;
                fz0 += f * dz;
            }

            if (second_valid && second_target != j) {
                const float dx = sx - x1;
                const float dy = sy - y1;
                const float dz = sz - z1;
                const float distSq = dx * dx + dy * dy + dz * dz + softening;
                const float dist = sqrtf(distSq);
                const float f = (G * mass1 * smass) / (distSq * dist);
                fx1 += f * dx;
                fy1 += f * dy;
                fz1 += f * dz;
            }
        }
        __syncthreads();
        tile_start += tile_count;
    }

    if (first_valid) {
        Particle p = in[first_target];
        p.vx += (fx0 / p.mass) * dt;
        p.vy += (fy0 / p.mass) * dt;
        p.vz += (fz0 / p.mass) * dt;
        p.x += p.vx * dt;
        p.y += p.vy * dt;
        p.z += p.vz * dt;
        out[first_target] = p;
    }

    if (second_valid) {
        Particle p = in[second_target];
        p.vx += (fx1 / p.mass) * dt;
        p.vy += (fy1 / p.mass) * dt;
        p.vz += (fz1 / p.mass) * dt;
        p.x += p.vx * dt;
        p.y += p.vy * dt;
        p.z += p.vz * dt;
        out[second_target] = p;
    }
}

struct Particle {
    float x, y, z;
    float vx, vy, vz;
    float mass;
};

extern "C" __global__ void nbody_step_naive(const Particle* in, Particle* out, int n, float dt) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i >= n) return;

    const float G = 1.0f;
    const float softening = 0.001f;

    float fx = 0.0f;
    float fy = 0.0f;
    float fz = 0.0f;

    for (int j = 0; j < n; j++) {
        if (i == j) continue;

        float dx = in[j].x - in[i].x;
        float dy = in[j].y - in[i].y;
        float dz = in[j].z - in[i].z;

        float distSq = fmaf(dx, dx, fmaf(dy, dy, fmaf(dz, dz, softening)));
        float invDist = rsqrtf(distSq);
        float invDistSq = invDist * invDist;
        float correction = fmaf(-0.5f * distSq, invDistSq, 1.5f);
        invDist *= correction;
        float invDistCubed = invDist * invDist * invDist;

        float f = (G * in[i].mass * in[j].mass) * invDistCubed;

        fx += f * dx;
        fy += f * dy;
        fz += f * dz;
    }

    Particle p = in[i];
    p.vx += (fx / p.mass) * dt;
    p.vy += (fy / p.mass) * dt;
    p.vz += (fz / p.mass) * dt;

    p.x += p.vx * dt;
    p.y += p.vy * dt;
    p.z += p.vz * dt;

    out[i] = p;
}

