        p.vx += (fx2 / p.mass) * dt;
        p.vy += (fy2 / p.mass) * dt;
        p.vz += (fz2 / p.mass) * dt;
        p.x += p.vx * dt;
        p.y += p.vy * dt;
        p.z += p.vz * dt;
        out[third_target] = p;
    }

    if (fourth_valid) {
        Particle p = in[fourth_target];
        p.vx += (fx3 / p.mass) * dt;
        p.vy += (fy3 / p.mass) * dt;
        p.vz += (fz3 / p.mass) * dt;
        p.x += p.vx * dt;
        p.y += p.vy * dt;
        p.z += p.vz * dt;
        out[fourth_target] = p;
    }
