        }

        #pragma unroll 32
        for (int k = 0; k < 32; ++k) {
            const float sx = __shfl_sync(0xffffffffu, tile_x, k);
            const float sy = __shfl_sync(0xffffffffu, tile_y, k);
            const float sz = __shfl_sync(0xffffffffu, tile_z, k);
            const float source_mass = __shfl_sync(0xffffffffu, tile_mass, k);

            if (k < remaining) {
                const int j = source_base + k;
                if (target_valid && i != j) {
                    const float dx = sx - p.x;
                    const float dy = sy - p.y;
                    const float dz = sz - p.z;

                    const float distSq = dx * dx + dy * dy + dz * dz + softening;
                    const float dist = sqrtf(distSq);
                    const float f = (G * p.mass * source_mass) / (distSq * dist);

                    fx += f * dx;
                    fy += f * dy;
                    fz += f * dz;
                }
            }
        }
    }

    if (target_valid) {
        p.vx += (fx / p.mass) * dt;
        p.vy += (fy / p.mass) * dt;
        p.vz += (fz / p.mass) * dt;

        p.x += p.vx * dt;
        p.y += p.vy * dt;
        p.z += p.vz * dt;

        out[i] = p;
    }
}

// Structure "Array of Structures" (AoS).
struct Particle {
    float x, y, z;
    float vx, vy, vz;
    float mass;
};

// Tiled variant: keep one target particle per thread and stage source
// particles in shared memory for reuse by the block's targets.
extern "C" __global__ void nbody_step_naive(const Particle* in, Particle* out, int n, float dt) {
    const int i = blockIdx.x * blockDim.x + threadIdx.x;

    // The launch configuration uses 256 threads. This is 256 * 7 floats
    // (7168 bytes), below the 49152-byte shared-memory limit.
    __shared__ Particle source_tile[256];

    const float G = 1.0f;
    const float softening = 0.001f;
    float fx = 0.0f;
    float fy = 0.0f;
    float fz = 0.0f;

    int tile_start = 0;
    while (tile_start < n) {
        const int remaining = n - tile_start;
        const int tile_count = remaining < blockDim.x ? remaining : blockDim.x;

        if (threadIdx.x < tile_count) {
            source_tile[threadIdx.x] = in[tile_start + threadIdx.x];
        }
        // All threads, including those outside the target tail, must reach
        // each block-wide barrier.
        __syncthreads();

        if (i < n) {
            for (int offset = 0; offset < tile_count; ++offset) {
                const int j = tile_start + offset;
                if (i == j) continue;

                float dx = source_tile[offset].x - in[i].x;
                float dy = source_tile[offset].y - in[i].y;
                float dz = source_tile[offset].z - in[i].z;

                float distSq = dx * dx + dy * dy + dz * dz + softening;
                float dist = sqrtf(distSq);

                float f = (G * in[i].mass * source_tile[offset].mass) / (distSq * dist);

                fx += f * dx;
                fy += f * dy;
                fz += f * dz;
            }
        }

        // Synchronize before overwriting a tile, but no extra barrier is
        // needed once the final tile has been consumed.
        if (remaining > blockDim.x) {
            __syncthreads();
        }
        tile_start += tile_count;
    }

    if (i >= n) return;

    // Explicit Euler integration, with the baseline arithmetic unchanged.
    Particle p = in[i];
    p.vx += (fx / p.mass) * dt;
    p.vy += (fy / p.mass) * dt;
    p.vz += (fz / p.mass) * dt;

    p.x += p.vx * dt;
    p.y += p.vy * dt;
    p.z += p.vz * dt;

    out[i] = p;
}

// Structure "Array of Structures" (AoS) : intuitive mais naïve sur GPU
// car elle empêche la coalescence parfaite des accès mémoire.
struct Particle {
    float x, y, z;
    float vx, vy, vz;
    float mass;
};

__device__ __forceinline__ void update_target(const Particle* in, Particle* out, int i, int n, float dt) {
    const float G = 1.0f;
    const float softening = 0.001f;
    const Particle target = in[i];

    float fx = 0.0f;
    float fy = 0.0f;
    float fz = 0.0f;

    for (int j = 0; j < n; j++) {
        if (i == j) continue;

        float dx = in[j].x - target.x;
        float dy = in[j].y - target.y;
        float dz = in[j].z - target.z;

        float distSq = dx * dx + dy * dy + dz * dz + softening;
        float dist = sqrtf(distSq);
        float f = (G * target.mass * in[j].mass) / (distSq * dist);

        fx += f * dx;
        fy += f * dy;
        fz += f * dz;
    }

    Particle p = target;
    p.vx += (fx / p.mass) * dt;
    p.vy += (fy / p.mass) * dt;
    p.vz += (fz / p.mass) * dt;

    p.x += p.vx * dt;
    p.y += p.vy * dt;
    p.z += p.vz * dt;

    out[i] = p;
}

// Direct two-target microtile: each thread handles adjacent target pairs.
// Pair assignment uses the actual grid dimensions, so it covers N exactly
// even when the number of launched threads differs from N.
extern "C" __global__ void nbody_step_naive(const Particle* in, Particle* out, int n, float dt) {
    if (n <= 0) return;

    const long long total_threads = (long long)gridDim.x * (long long)blockDim.x;
    if (total_threads <= 0) return;

    const long long thread_index = (long long)blockIdx.x * (long long)blockDim.x + (long long)threadIdx.x;
    const long long pair_stride = 2LL * total_threads;

    for (long long i = 2LL * thread_index; i < (long long)n; i += pair_stride) {
        update_target(in, out, (int)i, n, dt);
        if (i + 1LL < (long long)n) {
            update_target(in, out, (int)(i + 1LL), n, dt);
        }
    }
}

